'use strict';

const fs = require('fs');
const tokens = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
if (tokens.length === 1 && tokens[0] === '') process.exit(0);

let pos = 0;
const L = Number(tokens[pos++]);
const C = Number(tokens[pos++]);
const grid = Array.from({ length: L }, () => []);
const present = new Array(676).fill(false);
const equations = [];

function variableId(name) {
  return (name.charCodeAt(0) - 97) * 26 + name.charCodeAt(1) - 97;
}

for (let r = 0; r < L; r++) {
  const counts = new Map();

  for (let c = 0; c < C; c++) {
    const id = variableId(tokens[pos++]);
    grid[r].push(id);
    present[id] = true;
    counts.set(id, (counts.get(id) || 0) + 1);
  }

  equations.push({
    counts,
    remaining: BigInt(tokens[pos++]),
    unknown: counts.size
  });
}

const columnSums = [];
for (let c = 0; c < C; c++) columnSums.push(BigInt(tokens[pos++]));

for (let c = 0; c < C; c++) {
  const counts = new Map();

  for (let r = 0; r < L; r++) {
    const id = grid[r][c];
    counts.set(id, (counts.get(id) || 0) + 1);
  }

  equations.push({
    counts,
    remaining: columnSums[c],
    unknown: counts.size
  });
}

const incidence = Array.from({ length: 676 }, () => []);
for (let e = 0; e < equations.length; e++) {
  for (const [id, coefficient] of equations[e].counts) {
    incidence[id].push([e, coefficient]);
  }
}

const values = new Array(676);
const known = new Array(676).fill(false);
const queue = [];

for (let e = 0; e < equations.length; e++) {
  if (equations[e].unknown === 1) queue.push(e);
}

for (let head = 0; head < queue.length; head++) {
  const e = queue[head];
  const equation = equations[e];
  if (equation.unknown !== 1) continue;

  let id = -1;
  let coefficient = 0;
  for (const [candidate, count] of equation.counts) {
    if (!known[candidate]) {
      id = candidate;
      coefficient = count;
      break;
    }
  }

  if (id === -1) continue;

  const value = equation.remaining / BigInt(coefficient);
  values[id] = value;
  known[id] = true;

  for (const [eqIndex, count] of incidence[id]) {
    const current = equations[eqIndex];
    current.remaining -= BigInt(count) * value;
    current.unknown--;

    if (current.unknown === 1) queue.push(eqIndex);
  }
}

const output = [];
for (let id = 0; id < 676; id++) {
  if (present[id]) {
    const name = String.fromCharCode(97 + Math.floor(id / 26)) +
      String.fromCharCode(97 + (id % 26));
    output.push(`${name} ${values[id]}`);
  }
}

console.log(output.join('\n'));
